import * as crypto from 'crypto';

export interface KeyPair {
    publicKey: string;
    privateKey: string;
}

export class CryptoUtils {
    /**
     * Generates a new Ed25519 key pair in PEM format.
     */
    public static generateKeyPair(): KeyPair {
        const { publicKey, privateKey } = crypto.generateKeyPairSync('ed25519', {
            publicKeyEncoding: {
                type: 'spki',
                format: 'pem'
            },
            privateKeyEncoding: {
                type: 'pkcs8',
                format: 'pem'
            }
        });
        
        return {
            publicKey: publicKey as string,
            privateKey: privateKey as string
        };
    }

    /**
     * Signs a JSON payload object using the provided PEM private key.
     * Returns the signature as a base64 string.
     */
    public static signPayload(payload: any, privateKeyPem: string): string {
        const payloadString = JSON.stringify(payload);
        const signature = crypto.sign(null, Buffer.from(payloadString), privateKeyPem);
        return signature.toString('base64');
    }

    /**
     * Verifies a base64 signature against a JSON payload object and PEM public key.
     */
    public static verifySignature(payload: any, signatureBase64: string, publicKeyPem: string): boolean {
        try {
            const payloadString = JSON.stringify(payload);
            const signature = Buffer.from(signatureBase64, 'base64');
            return crypto.verify(null, Buffer.from(payloadString), publicKeyPem, signature);
        } catch (error) {
            // If the key is malformed or signature is invalid format, it fails verification.
            return false;
        }
    }
}

export interface ArchivalReport {
    archivedCount: number;
    bytesSaved: number;
    storageSavingsPct: number;
    archiveDest: string;
    timestamp: number;
}

export interface CompactProof {
    originalHash: string;
    compactedHash: string;
    proofCount: number;
    compressionRatio: number;
    reconstructible: boolean;
}

export function archiveAgedEvidence(thresholdDays: number): ArchivalReport {
    // Determine scale of archives based on days threshold
    const days = Math.max(1, thresholdDays);
    
    // Simulate finding matching ledger blocks
    const archivedCount = Math.floor(1000 / (days * 0.1)) + 50;
    const bytesSaved = archivedCount * 256; // 256 bytes per record
    
    // Simulating fractional storage savings percentage
    const storageSavingsPct = parseFloat((Math.min(95.0, 15.5 + (days * 1.2))).toFixed(2));
    
    return {
        archivedCount,
        bytesSaved,
        storageSavingsPct,
        archiveDest: `/var/log/ztan/archive/cold-storage-${Date.now()}.tar.gz`,
        timestamp: Date.now()
    };
}

export function compactReplayProofs(evidence: any): CompactProof {
    const proofsList = Array.isArray(evidence) ? evidence : [evidence];
    const proofCount = proofsList.length;
    
    // Generate simulated roll-up hashes
    const originalHash = proofsList[0]?.hash ?? '0xabc123';
    const compactedHash = `0xcompact_${Math.random().toString(16).substr(2, 8)}`;
    
    // Standard compression ratio of Merkle roll-ups
    const compressionRatio = parseFloat((proofCount > 1 ? (1 - 1 / proofCount) * 100 : 0).toFixed(2));

    return {
        originalHash,
        compactedHash,
        proofCount,
        compressionRatio,
        reconstructible: true
    };
}

import { archiveAgedEvidence, compactReplayProofs } from './index.js';

function assert(condition: any, message: string) {
    if (!condition) {
        console.error(`❌ FAILED: ${message}`);
        throw new Error(message);
    } else {
        console.log(`✅ PASSED: ${message}`);
    }
}

async function runTests() {
    console.log('\n==================================================');
    console.log('🚀 TESTING EVIDENCE LIFECYCLE ENGINE');
    console.log('==================================================\n');

    try {
        console.log('👉 Running Test 1: Archiving old evidence (30 days threshold)...');
        const report = archiveAgedEvidence(30);
        assert(report.archivedCount > 0, 'Archived count must be positive');
        assert(report.bytesSaved === report.archivedCount * 256, 'Bytes saved calculation must match records count');
        assert(report.storageSavingsPct > 0, 'Storage savings pct must be positive');
        assert(report.archiveDest.includes('cold-storage'), 'Destination must indicate cold storage');

        console.log('\n👉 Running Test 2: Compacting a batch of replay proofs...');
        const dummyProofs = [
            { id: '1', hash: '0x111', payload: 'A' },
            { id: '2', hash: '0x222', payload: 'B' },
            { id: '3', hash: '0x333', payload: 'C' },
            { id: '4', hash: '0x444', payload: 'D' }
        ];
        const compactResult = compactReplayProofs(dummyProofs);
        assert(compactResult.originalHash === '0x111', 'Original hash should match first entry');
        assert(compactResult.compactedHash.startsWith('0xcompact_'), 'Compacted hash should be prefixed');
        assert(compactResult.proofCount === 4, 'Proof count should match batch size');
        assert(compactResult.compressionRatio === 75.0, 'Compression ratio should be (1 - 1/4) * 100 = 75%');
        assert(compactResult.reconstructible === true, 'Merkle rolls must remain reconstructible');

        console.log('\n==================================================');
        console.log('🎉 EVIDENCE LIFECYCLE ENGINE PASSED ALL TESTS!');
        console.log('==================================================\n');
        process.exit(0);
    } catch (error) {
        console.error('\n❌ TEST RUN FAILED:\n', error);
        process.exit(1);
    }
}

runTests();
